import { isNil } from 'lodash';

/**
 * Returns all specified fields from an array
 *
 * @param {array} array - Array of items.
 * @param {string} fieldName - the field to get
 *
 * @returns {array} arr - array of field values.
 */
export function getMappedField(array = [], fieldName) {
  if (!Array.isArray(array) || array.length === 0) {
    return [];
  }

  return array.map((item) => item[fieldName]);
}

/**
 * Returns all ids from an array.
 *
 * @param {array} array - Array of items.
 *
 * @returns {array} arr - Array of ids.
 */
export function getIds(array) {
  return getMappedField(array, 'id');
}

/**
 * Returns all label from an array.
 *
 * @param {array} array - Array of items.
 *
 * @returns {array} arr - Array of label.
 */
export function getLabels(array) {
  return getMappedField(array, 'label');
}

/**
 * Returns the title of the list.
 * This is a mixture of template title and list instance title.
 *
 * @param {object} listTemplateTitle - The listTemplate title
 * @param {string} listInstanceTitle - The listInstance title
 *
 * @returns {string} title - The listTemplate and listInstance title
 */
export function getTitle(listTemplateTitle, listInstanceTitle) {
  if (!isNil(listInstanceTitle)) {
    return `${listInstanceTitle} (${listTemplateTitle})`;
  }

  if (!isNil(listTemplateTitle)) {
    return listTemplateTitle;
  }

  return '[Template Deleted]';
}
